  const refs = await ownNotebookRefs(rpc, userName);
  let match = null;
  for (const ref of refs.filter((v) => v !== configuredRef)) {
    let candidate;
    try {
      candidate = await rpc("GetKernel", { userName, kernelSlug: ref.split("/")[1] });
    } catch (e) {
      if ([403, 404].includes(e.http_status || e.status)) continue;
      throw e;
    }
    if (await matchesRun(candidate, run, { configuredRef, managerUrl })) {
