schema:
CREATE TABLE IF NOT EXISTS runs (
  id TEXT PRIMARY KEY, agent_hash TEXT NOT NULL, requested REAL NOT NULL,
  started REAL, heartbeat REAL, service TEXT NOT NULL DEFAULT 'submitted',
  kaggle_state TEXT NOT NULL DEFAULT 'SUBMITTING', version TEXT,
  url TEXT NOT NULL DEFAULT '', stop INTEGER NOT NULL DEFAULT 0,
  ended REAL, active INTEGER NOT NULL DEFAULT 1, note TEXT NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_run ON runs(active) WHERE active = 1;
CREATE INDEX IF NOT EXISTS runs_recent ON runs(requested DESC);

-- Additive migration: does not modify runs or existing Secrets.
CREATE TABLE IF NOT EXISTS device_pairings (
 id TEXT PRIMARY KEY, poll_hash TEXT NOT NULL, pkce TEXT NOT NULL,
 browser_hash TEXT, ip_hash TEXT NOT NULL, created REAL NOT NULL, expires REAL NOT NULL,
 state TEXT NOT NULL DEFAULT 'pending', language TEXT NOT NULL DEFAULT 'en'
);
CREATE INDEX IF NOT EXISTS pairings_ip ON device_pairings(ip_hash,created);
CREATE TABLE IF NOT EXISTS studio_devices (
 id TEXT PRIMARY KEY, manager_hash TEXT NOT NULL UNIQUE, model_hash TEXT NOT NULL UNIQUE,
 created REAL NOT NULL, expires REAL NOT NULL, revoked INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS studio_installation (
 id TEXT PRIMARY KEY, manifest TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS provider_credentials (
 provider TEXT PRIMARY KEY, sealed TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
 refresh_state TEXT NOT NULL DEFAULT 'ready'
);

CREATE TABLE IF NOT EXISTS studio_options (
 name TEXT PRIMARY KEY, value TEXT NOT NULL
);
